/**
 * Discover view, fragment, and fused-former dependencies.
 */
import { isFusedFormer } from "./former-nodes.js";
import { liveOf } from "./ir.js";
import { foldFormerNode } from "./schema.js";
import { walkValueTree } from "./value-tree.js";
import { viewLineIR } from "./view-lowering.js";
/** Every view a former's selections consult, by name. */
export function viewChannelsOfFormer(ref) {
    const channels = [];
    foldFormerNode(ref.body, {
        op: (op) => {
            if (viewLineIR(op)) {
                channels.push({ name: op.view, live: liveOf(op) });
            }
        },
    });
    return channels;
}
/** Every fragment a former's records splice. */
export function fragmentChannelsOfFormer(ref) {
    const channels = [];
    foldFormerNode(ref.body, {
        node: (node) => {
            if (node.node !== "former")
                return;
            channels.push({ name: node.former, live: liveOf(node) });
        },
        splice: (use) => {
            channels.push({ name: use.fragment, live: liveOf(use) });
        },
    });
    return channels;
}
/** Every fused former referenced in a mapping's values, recursively. */
export function fusedFormersOf(mapping) {
    const found = [];
    walkValueTree(mapping, (value) => {
        if (!isFusedFormer(value))
            return;
        found.push(value);
        return false;
    });
    return found;
}
/** The views one view's blocks rest on, by name with definition-site refs. */
export function viewChannelsOfView(ref) {
    const channels = [];
    for (const block of ref.alternatives) {
        for (const op of block) {
            if (viewLineIR(op)) {
                channels.push({ name: op.view, live: liveOf(op) });
            }
        }
    }
    return channels;
}
